export const LOGO_VERSION_BY_ID: Record<string, LogoVersion> = Object.fromEntries(
  LOGO_VERSIONS.map((v) => [v.id, v])
)

export const LOGO_CUT_BY_ASSET_KEY: Record<string, { version: LogoVersion; cut: LogoCut }> = (() => {
  const out: Record<string, { version: LogoVersion; cut: LogoCut }> = {}
  for (const version of LOGO_VERSIONS) {
    for (const cut of version.cuts) {
      out[cut.assetKey] = { version, cut }
      for (const alias of cut.aliases) {
        if (!alias.includes('/') && !out[alias]) out[alias] = { version, cut }
      }
    }
  }
  return out
})()

