export function versionForAssetKey(assetKey: string): LogoVersion | null {
  return LOGO_CUT_BY_ASSET_KEY[assetKey]?.version ?? null
}

export function cutForAssetKey(assetKey: string): LogoCut | null {
  return LOGO_CUT_BY_ASSET_KEY[assetKey]?.cut ?? null
}

export function cutsForSurface(version: LogoVersion, surface: 'light' | 'dark'): LogoCut[] {
  return version.cuts.filter((cut) => cut.surface === surface || cut.surface === 'both')
}

export function bestCutForSurface(version: LogoVersion, surface: 'light' | 'dark'): LogoCut | null {
  const cuts = cutsForSurface(version, surface)
  if (!cuts.length) return null
  const rank = (s: LogoCut['status']): number => (s === 'READY' ? 0 : s === 'LEGACY' ? 1 : s === 'CANDIDATE' ? 2 : 3)
  const conf = (c: LogoCut['confidence']): number => (c === 'high' ? 0 : c === 'medium' ? 1 : 2)
  return [...cuts].sort((a, b) => rank(a.status) - rank(b.status) || conf(a.confidence) - conf(b.confidence))[0]
}
